10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	
14	// Lazy-loaded route components for code splitting
15	const Index = lazy(() => import("./pages/Index"));
16	const Auth = lazy(() => import("./pages/Auth"));
17	const Admin = lazy(() => import("./pages/Admin"));
18	const Settings = lazy(() => import("./pages/Settings"));
19	const Profile = lazy(() => import("./pages/Profile"));
20	const Billing = lazy(() => import("./pages/Billing"));
21	const NotFound = lazy(() => import("./pages/NotFound"));
22	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
23	const BookDemo = lazy(() => import("./pages/BookDemo"));
24	const RequestFeature = lazy(() => import("./pages/RequestFeature"));
25	const Changelog = lazy(() => import("./pages/Changelog"));
26	const LandingPage = lazy(() => import("@/components/LandingPage"));
27	
28	const queryClient = new QueryClient();
29	
30	const PageLoader = () => null;
31	
32	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
33	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
34	  const { isAdmin, loading } = useAuth();
35	
36	  // Don't block rendering while loading — only gate when we know maintenance is on
37	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
38	  return <>{children}</>;
39	};
40	
41	const RootRoute = () => {
42	  const { user, loading } = useAuth();
43	  if (loading) return <PageLoader />;
44	  return user ? <Index /> : <LandingPage />;
45	};
46	
47	const App = () => (
48	  <QueryClientProvider client={queryClient}>
49	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
50	      <AuthProvider>
51	        <TooltipProvider>
52	          <Sonner />
53	          <BrowserRouter>
54	            <SeoHead />
55	            <MaintenanceGate>
56	              <Suspense fallback={<PageLoader />}>
57	                <Routes>
58	                  <Route path="/auth" element={<Auth />} />
59	                  <Route path="/" element={<RootRoute />} />
60	                  <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
61	                  <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
62	                  <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
63	                  <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
64	                  <Route path="/book-demo" element={<BookDemo />} />
65	                  <Route path="/request-feature" element={<RequestFeature />} />
66	                  <Route path="/changelog" element={<Changelog />} />
67	                  <Route path="/payment/callback" element={<PaymentCallback />} />
68	                  <Route path="*" element={<NotFound />} />
69	                </Routes>
70	              </Suspense>
71	            </MaintenanceGate>
72	            <ChatWidget />
73	          </BrowserRouter>
74	        </TooltipProvider>
75	      </AuthProvider>
76	    </ThemeProvider>
77	  </QueryClientProvider>
78	);
79	
80	export default App;
